function validate([nums, k, limit]) {
  if (nums.length < 1 || nums.length > 150) return 'nums has 1 to 150 values.';
  if (nums.some(x => x < 0 || x > 12)) return 'Each value of nums is between 0 and 12.';
  if (k < -100000 || k > 100000) return 'k is between -10^5 and 10^5.';
  if (limit < 1 || limit > 5000) return 'limit is between 1 and 5000.';
  return null;
}

