function maxProduct(nums, k, limit) {
  const total = nums.reduce((sum, x) => sum + x, 0);
  if (Math.abs(k) > total) {
    return -1;
  }
  const over = limit + 1;
  const reachable = [new Map(), new Map()];
  for (const x of nums) {
    const updates = [[1, x, [Math.min(x, over)]]];
    for (let parity = 0; parity <= 1; parity++) {
      for (const [sum, products] of reachable[parity]) {
        const nextSum = parity === 0 ? sum + x : sum - x;
        const nextProducts = [];
        for (const product of products) {
          nextProducts.push(Math.min(product * x, over));
        }
        updates.push([1 - parity, nextSum, nextProducts]);
      }
    }
    for (const [parity, sum, products] of updates) {
      if (!reachable[parity].has(sum)) {
        reachable[parity].set(sum, new Set());
      }
      const known = reachable[parity].get(sum);
      for (const product of products) {
        known.add(product);
      }
    }
  }
  let best = -1;
  for (let parity = 0; parity <= 1; parity++) {
    for (const product of reachable[parity].get(k) ?? []) {
      if (product <= limit) {
        best = Math.max(best, product);
      }
    }
  }
  return best;
}

