function maxProduct(nums, k, limit) {
  // Try every non-empty subset of positions, kept in their original order.
  let best = -1;
  for (let mask = 1; mask < 1 << nums.length; mask++) {
    let alternating = 0;
    let product = 1;
    let position = 0;
    for (let i = 0; i < nums.length; i++) {
      if (!(mask & (1 << i))) continue;
      alternating += position % 2 === 0 ? nums[i] : -nums[i];
      product *= nums[i];
      position++;
    }
    if (alternating === k && product <= limit) best = Math.max(best, product);
  }
  return best;
}

