function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  let n = pick(1, 12);
  let limit = rand() < 0.5 ? pick(1, 60) : pick(1, 5000);
  if (size === 'large') {
    // Full-length arrays get a small limit and shorter arrays a large one, so the case stays quick to judge.
    const long = rand() < 0.5;
    n = long ? 150 : pick(40, 50);
    limit = long ? pick(50, 150) : pick(3000, 5000);
  }
  const style = rand();
  const nums = [];
  for (let i = 0; i < n; i++) {
    if (style < 0.3) nums.push(rand() < 0.5 ? 1 : pick(0, 12));
    else if (style < 0.45) nums.push(pick(0, 3));
    else nums.push(pick(0, 12));
  }
  // Usually aim k at the alternating sum of a random subsequence, so that an answer exists.
  let k = pick(-30, 30);
  if (rand() < 0.75) {
    k = 0;
    let length = 0;
    for (const x of nums) {
      if (rand() < 0.4) {
        k += length % 2 === 0 ? x : -x;
        length++;
      }
    }
  }
  return [nums, k, limit];
}
